import{_ as e,o as d,c as l,a5 as a}from"./chunks/framework.a5no_H3L.js";const m=JSON.parse('{"title":"常用函数速查","description":"本页只列常用函数，不覆盖完整函数库。参数、返回类型和适用版本以目标 MySQL 版本参考手册为准；表达式包索引列时可能无法直接使用普通索引，见索引使用。","frontmatter":{},"headers":[],"relativePath":"mysql/reference/functions.md","filePath":"mysql/reference/functions.md"}'),c={name:"mysql/reference/functions.md"};function n(s,t,r,i,f,o){return d(),l("div",null,[...t[0]||(t[0]=[a('<h1 id="常用函数速查" tabindex="-1" data-src-line="1" data-src-file="mysql/reference/functions.md">常用函数速查 <a class="header-anchor" href="#常用函数速查" aria-label="Permalink to &quot;常用函数速查&quot;">​</a></h1><blockquote data-src-line="3" data-src-file="mysql/reference/functions.md"><p data-src-line="3" data-src-file="mysql/reference/functions.md">本页只列常用函数，不覆盖完整函数库。参数、返回类型和适用版本以目标 MySQL 版本参考手册为准；表达式包索引列时可能无法直接使用普通索引，见<a href="./../03-index/chapter-03-index-usage.html">索引使用</a>。</p></blockquote><h2 id="字符串函数" tabindex="-1" data-src-line="5" data-src-file="mysql/reference/functions.md">字符串函数 <a class="header-anchor" href="#字符串函数" aria-label="Permalink to &quot;字符串函数&quot;">​</a></h2><table tabindex="0"><thead data-src-line="7" data-src-file="mysql/reference/functions.md"><tr data-src-line="7" data-src-file="mysql/reference/functions.md"><th style="text-align:left;">函数</th><th style="text-align:left;">说明</th><th style="text-align:left;">示例</th></tr></thead><tbody data-src-line="9" data-src-file="mysql/reference/functions.md"><tr data-src-line="9" data-src-file="mysql/reference/functions.md"><td style="text-align:left;"><code>CONCAT(s1, s2, ...)</code></td><td style="text-align:left;">拼接字符串</td><td style="text-align:left;"><code>CONCAT(&#39;Hello&#39;, &#39; &#39;, &#39;World&#39;)</code></td></tr><tr data-src-line="10" data-src-file="mysql/reference/functions.md"><td style="text-align:left;"><code>CONCAT_WS(sep, s1, s2)</code></td><td style="text-align:left;">用分隔符拼接</td><td style="text-align:left;"><code>CONCAT_WS(&#39;-&#39;, &#39;2026&#39;, &#39;08&#39;, &#39;31&#39;)</code></td></tr><tr data-src-line="11" data-src-file="mysql/reference/functions.md"><td style="text-align:left;"><code>SUBSTRING(s, pos, len)</code></td><td style="text-align:left;">截取子串</td><td style="text-align:left;"><code>SUBSTRING(&#39;Hello&#39;, 1, 3)</code> → <code>Hel</code></td></tr><tr data-src-line="12" data-src-file="mysql/reference/functions.md"><td style="text-align:left;"><code>LENGTH(s)</code></td><td style="text-align:left;">字节长度</td><td style="text-align:left;"><code>LENGTH(&#39;你好&#39;)</code> → 6（utf8mb4）</td></tr><tr data-src-line="13" data-src-file="mysql/reference/functions.md"><td style="text-align:left;"><code>CHAR_LENGTH(s)</code></td><td style="text-align:left;">字符长度</td><td style="text-align:left;"><code>CHAR_LENGTH(&#39;你好&#39;)</code> → 2</td></tr><tr data-src-line="14" data-src-file="mysql/reference/functions.md"><td style="text-align:left;"><code>TRIM(s)</code></td><td style="text-align:left;">去首尾空格</td><td style="text-align:left;"><code>TRIM(&#39; hi &#39;)</code> → <code>hi</code></td></tr><tr data-src-line="15" data-src-file="mysql/reference/functions.md"><td style="text-align:left;"><code>REPLACE(s, from, to)</code></td><td style="text-align:left;">替换</td><td style="text-align:left;"><code>REPLACE(&#39;abc&#39;, &#39;b&#39;, &#39;X&#39;)</code> → <code>aXc</code></td></tr></tbody></table><h2 id="条件与-null" tabindex="-1" data-src-line="17" data-src-file="mysql/reference/functions.md">条件与 NULL <a class="header-anchor" href="#条件与-null" aria-label="Permalink to &quot;条件与 NULL&quot;">​</a></h2><table tabindex="0"><thead data-src-line="19" data-src-file="mysql/reference/functions.md"><tr data-src-line="19" data-src-file="mysql/reference/functions.md"><th style="text-align:left;">函数</th><th style="text-align:left;">说明</th><th style="text-align:left;">示例</th></tr></thead><tbody data-src-line="21" data-src-file="mysql/reference/functions.md"><tr data-src-line="21" data-src-file="mysql/reference/functions.md"><td style="text-align:left;"><code>IFNULL(expr1, expr2)</code></td><td style="text-align:left;"><code>expr1</code> 为 NULL 时返回 <code>expr2</code></td><td style="text-align:left;"><code>IFNULL(col, &#39;unknown&#39;)</code></td></tr><tr data-src-line="22" data-src-file="mysql/reference/functions.md"><td style="text-align:left;"><code>COALESCE(a, b, c)</code></td><td style="text-align:left;">返回第一个非 NULL 参数</td><td style="text-align:left;"><code>COALESCE(a, b, c)</code></td></tr><tr data-src-line="23" data-src-file="mysql/reference/functions.md"><td style="text-align:left;"><code>IF(condition, true_value, false_value)</code></td><td style="text-align:left;">简单条件表达式</td><td style="text-align:left;"><code>IF(status = 1, &#39;on&#39;, &#39;off&#39;)</code></td></tr><tr data-src-line="24" data-src-file="mysql/reference/functions.md"><td style="text-align:left;"><code>CASE ... WHEN ... THEN ... END</code></td><td style="text-align:left;">多分支条件表达式</td><td style="text-align:left;"><code>CASE status WHEN 1 THEN &#39;on&#39; ELSE &#39;off&#39; END</code></td></tr></tbody></table><p data-src-line="26" data-src-file="mysql/reference/functions.md"><code>COALESCE</code> 和 <code>IFNULL</code> 不限于字符串；聚合函数 <code>SUM</code>、<code>AVG</code>、<code>MAX</code> 和 <code>MIN</code> 通常忽略 NULL，但 <code>COUNT(*)</code> 统计行数，包含被统计列值为 NULL 的行。</p><h2 id="日期函数" tabindex="-1" data-src-line="28" data-src-file="mysql/reference/functions.md">日期函数 <a class="header-anchor" href="#日期函数" aria-label="Permalink to &quot;日期函数&quot;">​</a></h2><table tabindex="0"><thead data-src-line="30" data-src-file="mysql/reference/functions.md"><tr data-src-line="30" data-src-file="mysql/reference/functions.md"><th style="text-align:left;">函数</th><th style="text-align:left;">说明</th><th style="text-align:left;">示例</th></tr></thead><tbody data-src-line="32" data-src-file="mysql/reference/functions.md"><tr data-src-line="32" data-src-file="mysql/reference/functions.md"><td style="text-align:left;"><code>NOW()</code></td><td style="text-align:left;">当前日期时间</td><td style="text-align:left;"><code>2026-08-31 12:00:00</code></td></tr><tr data-src-line="33" data-src-file="mysql/reference/functions.md"><td style="text-align:left;"><code>CURDATE()</code></td><td style="text-align:left;">当前日期</td><td style="text-align:left;"><code>2026-08-31</code></td></tr><tr data-src-line="34" data-src-file="mysql/reference/functions.md"><td style="text-align:left;"><code>DATE_FORMAT(d, fmt)</code></td><td style="text-align:left;">格式化日期</td><td style="text-align:left;"><code>DATE_FORMAT(NOW(), &#39;%Y-%m-%d&#39;)</code></td></tr><tr data-src-line="35" data-src-file="mysql/reference/functions.md"><td style="text-align:left;"><code>DATEDIFF(d1, d2)</code></td><td style="text-align:left;">日期差（天）</td><td style="text-align:left;"><code>DATEDIFF(&#39;2026-12-31&#39;, &#39;2026-01-01&#39;)</code> → 364</td></tr><tr data-src-line="36" data-src-file="mysql/reference/functions.md"><td style="text-align:left;"><code>DATE_ADD(d, INTERVAL n unit)</code></td><td style="text-align:left;">日期加减</td><td style="text-align:left;"><code>DATE_ADD(NOW(), INTERVAL 7 DAY)</code></td></tr><tr data-src-line="37" data-src-file="mysql/reference/functions.md"><td style="text-align:left;"><code>UNIX_TIMESTAMP(d)</code></td><td style="text-align:left;">转时间戳</td><td style="text-align:left;"><code>UNIX_TIMESTAMP(NOW())</code></td></tr><tr data-src-line="38" data-src-file="mysql/reference/functions.md"><td style="text-align:left;"><code>FROM_UNIXTIME(ts)</code></td><td style="text-align:left;">时间戳转日期</td><td style="text-align:left;"><code>FROM_UNIXTIME(1693000000)</code></td></tr></tbody></table><h2 id="聚合函数" tabindex="-1" data-src-line="40" data-src-file="mysql/reference/functions.md">聚合函数 <a class="header-anchor" href="#聚合函数" aria-label="Permalink to &quot;聚合函数&quot;">​</a></h2><table tabindex="0"><thead data-src-line="42" data-src-file="mysql/reference/functions.md"><tr data-src-line="42" data-src-file="mysql/reference/functions.md"><th style="text-align:left;">函数</th><th style="text-align:left;">说明</th></tr></thead><tbody data-src-line="44" data-src-file="mysql/reference/functions.md"><tr data-src-line="44" data-src-file="mysql/reference/functions.md"><td style="text-align:left;"><code>COUNT(*)</code></td><td style="text-align:left;">当前分组或结果集的行数，包括被统计列值为 NULL 的行</td></tr><tr data-src-line="45" data-src-file="mysql/reference/functions.md"><td style="text-align:left;"><code>COUNT(col)</code></td><td style="text-align:left;"><code>col</code> 非 NULL 的行数</td></tr><tr data-src-line="46" data-src-file="mysql/reference/functions.md"><td style="text-align:left;"><code>COUNT(DISTINCT col)</code></td><td style="text-align:left;"><code>col</code> 非 NULL 的不同值数量</td></tr><tr data-src-line="47" data-src-file="mysql/reference/functions.md"><td style="text-align:left;"><code>SUM(col)</code></td><td style="text-align:left;">求和</td></tr><tr data-src-line="48" data-src-file="mysql/reference/functions.md"><td style="text-align:left;"><code>AVG(col)</code></td><td style="text-align:left;"><code>col</code> 非 NULL 值的平均值</td></tr><tr data-src-line="49" data-src-file="mysql/reference/functions.md"><td style="text-align:left;"><code>MAX(col)</code> / <code>MIN(col)</code></td><td style="text-align:left;">最大 / 最小值</td></tr><tr data-src-line="50" data-src-file="mysql/reference/functions.md"><td style="text-align:left;"><code>GROUP_CONCAT(col)</code></td><td style="text-align:left;">分组拼接；结果为 NULL 时默认返回 NULL，并受 <code>group_concat_max_len</code> 限制</td></tr></tbody></table><h2 id="数值函数" tabindex="-1" data-src-line="52" data-src-file="mysql/reference/functions.md">数值函数 <a class="header-anchor" href="#数值函数" aria-label="Permalink to &quot;数值函数&quot;">​</a></h2><table tabindex="0"><thead data-src-line="54" data-src-file="mysql/reference/functions.md"><tr data-src-line="54" data-src-file="mysql/reference/functions.md"><th style="text-align:left;">函数</th><th style="text-align:left;">说明</th><th style="text-align:left;">示例</th></tr></thead><tbody data-src-line="56" data-src-file="mysql/reference/functions.md"><tr data-src-line="56" data-src-file="mysql/reference/functions.md"><td style="text-align:left;"><code>ROUND(x, d)</code></td><td style="text-align:left;">四舍五入到 <code>d</code> 位小数</td><td style="text-align:left;"><code>ROUND(123.456, 2)</code> → <code>123.46</code></td></tr><tr data-src-line="57" data-src-file="mysql/reference/functions.md"><td style="text-align:left;"><code>TRUNCATE(x, d)</code></td><td style="text-align:left;">截断到 <code>d</code> 位小数</td><td style="text-align:left;"><code>TRUNCATE(123.456, 2)</code> → <code>123.45</code></td></tr><tr data-src-line="58" data-src-file="mysql/reference/functions.md"><td style="text-align:left;"><code>ABS(x)</code></td><td style="text-align:left;">绝对值</td><td style="text-align:left;"><code>ABS(-8)</code> → <code>8</code></td></tr><tr data-src-line="59" data-src-file="mysql/reference/functions.md"><td style="text-align:left;"><code>MOD(x, y)</code></td><td style="text-align:left;">取余</td><td style="text-align:left;"><code>MOD(7, 3)</code> → <code>1</code></td></tr></tbody></table><h2 id="窗口函数-8-0" tabindex="-1" data-src-line="61" data-src-file="mysql/reference/functions.md">窗口函数（8.0+） <a class="header-anchor" href="#窗口函数-8-0" aria-label="Permalink to &quot;窗口函数（8.0+）&quot;">​</a></h2><table tabindex="0"><thead data-src-line="63" data-src-file="mysql/reference/functions.md"><tr data-src-line="63" data-src-file="mysql/reference/functions.md"><th style="text-align:left;">函数</th><th style="text-align:left;">说明</th></tr></thead><tbody data-src-line="65" data-src-file="mysql/reference/functions.md"><tr data-src-line="65" data-src-file="mysql/reference/functions.md"><td style="text-align:left;"><code>ROW_NUMBER()</code></td><td style="text-align:left;">行号，无重复</td></tr><tr data-src-line="66" data-src-file="mysql/reference/functions.md"><td style="text-align:left;"><code>RANK()</code></td><td style="text-align:left;">排名，有并列会跳号</td></tr><tr data-src-line="67" data-src-file="mysql/reference/functions.md"><td style="text-align:left;"><code>DENSE_RANK()</code></td><td style="text-align:left;">排名，有并列不跳号</td></tr><tr data-src-line="68" data-src-file="mysql/reference/functions.md"><td style="text-align:left;"><code>LAG(col, n)</code></td><td style="text-align:left;">前 n 行的值</td></tr><tr data-src-line="69" data-src-file="mysql/reference/functions.md"><td style="text-align:left;"><code>LEAD(col, n)</code></td><td style="text-align:left;">后 n 行的值</td></tr><tr data-src-line="70" data-src-file="mysql/reference/functions.md"><td style="text-align:left;"><code>NTILE(n)</code></td><td style="text-align:left;">分成 n 组</td></tr><tr data-src-line="71" data-src-file="mysql/reference/functions.md"><td style="text-align:left;"><code>SUM() OVER()</code></td><td style="text-align:left;">累计求和</td></tr></tbody></table><p data-src-line="73" data-src-file="mysql/reference/functions.md">所有窗口函数都必须带 <code>OVER(...)</code> 子句；MySQL 8.0 起支持本节函数。</p><h2 id="json-函数" tabindex="-1" data-src-line="75" data-src-file="mysql/reference/functions.md">JSON 函数 <a class="header-anchor" href="#json-函数" aria-label="Permalink to &quot;JSON 函数&quot;">​</a></h2><table tabindex="0"><thead data-src-line="77" data-src-file="mysql/reference/functions.md"><tr data-src-line="77" data-src-file="mysql/reference/functions.md"><th style="text-align:left;">函数</th><th style="text-align:left;">说明</th><th style="text-align:left;">示例</th></tr></thead><tbody data-src-line="79" data-src-file="mysql/reference/functions.md"><tr data-src-line="79" data-src-file="mysql/reference/functions.md"><td style="text-align:left;"><code>JSON_EXTRACT(json, path)</code></td><td style="text-align:left;">按路径提取 JSON 值</td><td style="text-align:left;"><code>JSON_EXTRACT(doc, &#39;$.name&#39;)</code></td></tr><tr data-src-line="80" data-src-file="mysql/reference/functions.md"><td style="text-align:left;"><code>JSON_OBJECT(...)</code></td><td style="text-align:left;">创建 JSON 对象</td><td style="text-align:left;"><code>JSON_OBJECT(&#39;id&#39;, 1)</code></td></tr><tr data-src-line="81" data-src-file="mysql/reference/functions.md"><td style="text-align:left;"><code>JSON_ARRAY(...)</code></td><td style="text-align:left;">创建 JSON 数组</td><td style="text-align:left;"><code>JSON_ARRAY(1, 2, 3)</code></td></tr><tr data-src-line="82" data-src-file="mysql/reference/functions.md"><td style="text-align:left;"><code>JSON_VALID(expr)</code></td><td style="text-align:left;">判断字符串是否为有效 JSON</td><td style="text-align:left;"><code>JSON_VALID(payload)</code></td></tr></tbody></table><p data-src-line="84" data-src-file="mysql/reference/functions.md">JSON 查询、函数索引和生成列的完整用法见 <a href="./../06-sql-and-schema/chapter-03-json.html">JSON 类型</a>。</p>',19)])])}const x=e(c,[["render",n]]);export{m as __pageData,x as default};
